class Solution { public int minCost(int mt,int[][] e,int[] f) { int n=f.length;List<int[]>[] g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();for(int[] x:e){g[x[0]].add(new int[]{x[1],x[2]});g[x[1]].add(new int[]{x[0],x[2]});}int[][] d=new int[mt+1][n];for(int[] r:d)Arrays.fill(r,Integer.MAX_VALUE);d[0][0]=f[0];PriorityQueue<int[]>q=new PriorityQueue<>((a,b)->Integer.compare(a[0],b[0]));q.add(new int[]{f[0],0,0});while(!q.isEmpty()){int[] z=q.remove();int c=z[0],t=z[1],u=z[2];if(c!=d[t][u])continue;if(u==n-1)return c;for(int[] x:g[u]){int nt=t+x[1],nc=c+f[x[0]];if(nt<=mt&&nc<d[nt][x[0]]){d[nt][x[0]]=nc;q.add(new int[]{nc,nt,x[0]});}}}return -1;} }
